CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS schema_migrations(name text PRIMARY KEY, applied_at timestamptz DEFAULT now());
CREATE TABLE agencies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),demo_name text NOT NULL,category text NOT NULL,is_simulated boolean NOT NULL DEFAULT true CHECK(is_simulated));
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),username text UNIQUE NOT NULL,demo_name text NOT NULL,role text NOT NULL CHECK(role IN ('dispatcher','responder','supervisor','admin')),agency_id uuid REFERENCES agencies,password_hash text NOT NULL,active boolean DEFAULT true,created_at timestamptz DEFAULT now(),last_login_at timestamptz);
CREATE TABLE sessions(id_digest text PRIMARY KEY,user_id uuid REFERENCES users ON DELETE CASCADE,expires_at timestamptz NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE units(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),agency_id uuid REFERENCES agencies NOT NULL,callsign text UNIQUE NOT NULL,unit_type text NOT NULL,capability_tags text[] NOT NULL,dispatch_status text NOT NULL CHECK(dispatch_status IN ('AVAILABLE','BUSY','OFFLINE')),status_updated_at timestamptz DEFAULT now(),is_simulated boolean NOT NULL DEFAULT true CHECK(is_simulated));
CREATE TABLE responder_unit_memberships(user_id uuid REFERENCES users,unit_id uuid REFERENCES units,valid_from timestamptz DEFAULT now(),valid_to timestamptz,PRIMARY KEY(user_id,unit_id));
CREATE TABLE unit_current_locations(unit_id uuid PRIMARY KEY REFERENCES units,geom geography(Point,4326) NOT NULL,precision_m integer DEFAULT 100,recorded_at timestamptz DEFAULT now(),source text DEFAULT 'SYNTHETIC',is_simulated boolean DEFAULT true CHECK(is_simulated));
CREATE INDEX unit_geo ON unit_current_locations USING gist(geom);
CREATE TABLE incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),agency_id uuid REFERENCES agencies NOT NULL,public_reference text UNIQUE NOT NULL,source_channel text DEFAULT 'DEMO_WEB',category text NOT NULL,priority text DEFAULT 'MEDIUM',description_sanitised text NOT NULL CHECK(length(description_sanitised)<=500),geom geography(Point,4326) NOT NULL,landmark text NOT NULL,location_confidence text NOT NULL,location_accuracy_m integer DEFAULT 150,status text NOT NULL DEFAULT 'RECEIVED',reason_flags jsonb DEFAULT '[]',version integer NOT NULL DEFAULT 1,receipt_token_digest text UNIQUE NOT NULL,receipt_expires_at timestamptz NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),closed_at timestamptz,is_simulated boolean NOT NULL DEFAULT true CHECK(is_simulated));
CREATE INDEX incident_geo ON incidents USING gist(geom);
CREATE INDEX incident_status_date ON incidents(status,created_at);
CREATE TABLE assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid REFERENCES incidents NOT NULL,unit_id uuid REFERENCES units NOT NULL,status text NOT NULL,offered_by uuid REFERENCES users,offered_at timestamptz DEFAULT now(),expires_at timestamptz NOT NULL,accepted_by uuid REFERENCES users,accepted_at timestamptz,withdrawn_at timestamptz,decline_reason text,closed_at timestamptz);
CREATE UNIQUE INDEX one_current_incident_assignment ON assignments(incident_id) WHERE status IN ('OFFERED','ACCEPTED','ACTIVE');
CREATE UNIQUE INDEX one_current_unit_assignment ON assignments(unit_id) WHERE status IN ('OFFERED','ACCEPTED','ACTIVE');
CREATE INDEX assignment_incident ON assignments(incident_id);
CREATE TABLE incident_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid REFERENCES incidents NOT NULL,sequence integer NOT NULL,event_type text NOT NULL,actor_type text NOT NULL,actor_id uuid,aggregate_version integer NOT NULL,reason_code text NOT NULL,metadata jsonb NOT NULL,client_occurred_at timestamptz,server_occurred_at timestamptz NOT NULL,correlation_id uuid NOT NULL,prev_hash text NOT NULL,event_hash text NOT NULL,UNIQUE(incident_id,sequence));
CREATE FUNCTION protect_events() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Incident events are append-only'; END $$;
CREATE TRIGGER event_append_only BEFORE UPDATE OR DELETE ON incident_events FOR EACH ROW EXECUTE FUNCTION protect_events();
CREATE TABLE outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),aggregate_type text DEFAULT 'incident',aggregate_id uuid NOT NULL,event_id uuid REFERENCES incident_events NOT NULL,topic text NOT NULL,payload jsonb NOT NULL,created_at timestamptz DEFAULT now(),next_attempt_at timestamptz DEFAULT now(),attempts integer DEFAULT 0,delivered_at timestamptz,last_error text);
CREATE INDEX outbox_pending ON outbox_events(next_attempt_at) WHERE delivered_at IS NULL;
CREATE TABLE client_commands(idempotency_key text NOT NULL,actor_scope text NOT NULL,actor_id uuid,request_fingerprint text NOT NULL,command_type text NOT NULL,result_json jsonb NOT NULL,created_at timestamptz DEFAULT now(),expires_at timestamptz DEFAULT now()+interval '7 days',PRIMARY KEY(actor_scope,idempotency_key));
CREATE TABLE incident_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid REFERENCES incidents,created_by uuid REFERENCES users,role text NOT NULL,sanitized_text text NOT NULL,visibility text DEFAULT 'INTERNAL',created_at timestamptz DEFAULT now(),correction_of uuid REFERENCES incident_events);
CREATE TABLE incident_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),a_id uuid REFERENCES incidents,b_id uuid REFERENCES incidents,relation text NOT NULL,linked_by uuid REFERENCES users,reason text NOT NULL,created_at timestamptz DEFAULT now(),CHECK(a_id<>b_id));
CREATE TABLE citizen_feedback(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid REFERENCES incidents UNIQUE,receipt_token_scope text NOT NULL,response_clarity_score integer CHECK(response_clarity_score BETWEEN 1 AND 5),free_text text,submitted_at timestamptz DEFAULT now(),reviewed_at timestamptz);
CREATE TABLE supervisor_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid REFERENCES incidents,reviewer_id uuid REFERENCES users,review_type text DEFAULT 'CONTEXT',reason text NOT NULL,finding_text text NOT NULL,created_at timestamptz DEFAULT now(),resolved_at timestamptz);
CREATE TABLE audit_checkpoints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),checkpoint_at timestamptz DEFAULT now(),scope text NOT NULL,root_hash text NOT NULL,signer_key_id text DEFAULT 'DEMO_UNSIGNED',signature text,anchor_reference text,verification_status text DEFAULT 'LOCAL_ONLY');
CREATE TABLE simulation_scenarios(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,title text NOT NULL,seed_json jsonb NOT NULL,expected_results_json jsonb NOT NULL,enabled boolean DEFAULT true);
CREATE TABLE scenario_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scenario_id uuid REFERENCES simulation_scenarios,started_by uuid REFERENCES users,seed integer NOT NULL,started_at timestamptz DEFAULT now(),completed_at timestamptz,results_json jsonb);
CREATE TABLE simulation_settings(key text PRIMARY KEY,value jsonb NOT NULL);
CREATE TABLE security_audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid,action text NOT NULL,resource_kind text,resource_id text,occurred_at timestamptz DEFAULT now(),ip_hash text,result text NOT NULL);
